-- Courses are created and edited in the control panel. The former course_prices table becomes public.courses
-- (every column the public course page needs) and course_prices stays as a view so the payments function keeps working.
-- "published_on_site" and "enrol_open" are the two toggles: the control panel publishes the course file to the website
-- repository when the first is on, and the site shows "Enrol now" when the second is on. Run after 0008.

alter table public.course_prices rename to courses;
alter table public.courses
  add column if not exists subtitle          text,
  add column if not exists summary           text,
  add column if not exists area              text,
  add column if not exists level             text,
  add column if not exists duration          text,
  add column if not exists unit              text not null default 'modules',
  add column if not exists unit_note         text,
  add column if not exists access            text,
  add column if not exists outcomes          jsonb not null default '[]'::jsonb,
  add column if not exists about             jsonb not null default '[]'::jsonb,
  add column if not exists includes          jsonb not null default '[]'::jsonb,
  add column if not exists kit               jsonb,
  add column if not exists who_for           jsonb not null default '[]'::jsonb,
  add column if not exists not_for           jsonb not null default '[]'::jsonb,
  add column if not exists faq               jsonb not null default '[]'::jsonb,
  add column if not exists sort_order        integer not null default 99,
  add column if not exists featured          boolean not null default false,
  add column if not exists enrol_open        boolean not null default false,
  add column if not exists published_on_site boolean not null default false,
  add column if not exists site_published_at timestamptz,
  add column if not exists created_at        timestamptz not null default now();

create or replace view public.course_prices with (security_invoker = true) as
  select slug, title, price_inr, active, updated_at from public.courses;

-- Seed from content/courses/*.json (the courses already on the website).
insert into public.courses (slug, title, price_inr, active, subtitle, summary, area, level, duration, unit, unit_note, access, outcomes, about, includes, kit, who_for, not_for, faq, sort_order, featured, enrol_open, published_on_site, site_published_at)
values ('copyright-and-design-registration', 'Copyright and Design Registration', 4999, true, 'File a copyright application on Form XIV, clear the discrepancy letter, and register a design that survives a novelty objection.', 'The two filings everyone assumes are easy, until the discrepancy letter or the novelty objection arrives. Six modules, twelve exercises, both offices covered.', 'Copyright', 'Beginner', 'About 9 hours', 'modules', '', 'Lifetime access',
  '["Classify a work correctly and identify its owner before you touch the form","Prepare a Form XIV with a Statement of Particulars that does not invite a discrepancy","Obtain and file the Section 45 search certificate for artistic works used as labels","Answer a discrepancy letter inside the thirty-day window","Assess whether a product shape is registrable as a design, and what prior publication kills it","Prepare a design application with correct representations, Locarno class and statement of novelty","Respond to a novelty objection, and know when to switch strategy to a shape mark instead"]'::jsonb, '["Copyright and design registration are the filings most often handed to the newest person in the room, on the theory that they are simple. They are simple until the Copyright Office sends a discrepancy letter with thirty days to reply, or the Design Wing objects that your representations show two designs, not one.","This course covers both offices end to end, on real applications, discrepancy letters and examination reports. It also covers the question that sits between them and trademark law: for a product shape, which protection do you actually want, and in what order?","It is our shortest course and the one we recommend starting with if you are new to filings."]'::jsonb, '["12 drafting exercises with model answers","Form XIV and Statement of Particulars templates","Discrepancy reply template","Design representation checklist and Locarno quick reference","Shape protection decision tree","Lifetime access and updates"]'::jsonb, null, '["Paralegals, trainees and first-year associates handling filings","Founders in consumer products, media, software and fashion","Trademark practitioners who get asked about designs and do not want to guess"]'::jsonb, '["You want copyright litigation or fair-dealing doctrine","You are already filing designs weekly without objections"]'::jsonb, '[{"q":"Does it cover international design filings?","a":"Hague system filings are mentioned, with a comparison of what changes. The drafting work is Indian."}]'::jsonb, 4, false, false, true, now())
on conflict (slug) do update set subtitle = excluded.subtitle, summary = excluded.summary, area = excluded.area, level = excluded.level, duration = excluded.duration, unit = excluded.unit, unit_note = excluded.unit_note, access = excluded.access,
  outcomes = excluded.outcomes, about = excluded.about, includes = excluded.includes, kit = excluded.kit, who_for = excluded.who_for, not_for = excluded.not_for, faq = excluded.faq, sort_order = excluded.sort_order, featured = excluded.featured, enrol_open = excluded.enrol_open, published_on_site = true, site_published_at = coalesce(public.courses.site_published_at, now());

insert into public.courses (slug, title, price_inr, active, subtitle, summary, area, level, duration, unit, unit_note, access, outcomes, about, includes, kit, who_for, not_for, faq, sort_order, featured, enrol_open, published_on_site, site_published_at)
values ('ip-licensing-and-contracts', 'IP Licensing and Contracts', 9999, true, 'Draft, negotiate and close the agreements that make IP worth money: trademark licences, technology and software licences, assignments, and the clauses that decide every dispute.', 'Seven modules built around real licences, with a negotiation simulation played from both sides. You leave with a clause bank you have drafted yourself.', 'Licensing', 'Intermediate', 'About 14 hours', 'modules', '', 'Lifetime access',
  '["Write a due diligence memo on an IP portfolio that tells the client what they are actually buying","Draft a grant clause that gives away exactly what was agreed and nothing more","Draft a trademark licence with quality-control provisions that will hold up in India","Separate a software licence from a SaaS subscription and draft the IP clauses for each","Structure and draft a royalty schedule, with audit rights that get used","Draft a copyright assignment that satisfies Section 19 and an employee IP clause that covers the gap the statute leaves","Negotiate the ten clauses that are always negotiated, from either side of the table"]'::jsonb, '["Licensing is where IP meets money, and where most of the drafting errors that end in litigation are made. This course is for the lawyer who has to turn a term sheet into a signed agreement and the founder who has to read what comes back.","You will work with six real agreements: a food franchise, a pharma technology transfer, a SaaS contract, a brand licence for a celebrity venture, a software assignment and a cross-border patent licence. Each exercise asks you to draft or redraft a clause before you see ours.","The course ends with a two-sided negotiation simulation. You draft the licensor''s position, then the licensee''s markup, then the compromise. Most students report that this module alone changed how they read contracts."]'::jsonb, '["16 drafting exercises with model answers","Six real agreements, anonymised and annotated","Clause bank: grant, quality control, royalty, audit, termination, assignment","Negotiation simulation with positions for both sides","Due diligence checklist","Monthly live drafting clinic, replays included","Lifetime access and updates"]'::jsonb, null, '["Transactional lawyers who have been handed their first licence","In-house counsel at brand, pharma and technology companies","Founders negotiating with distributors, franchisees or investors","IP prosecution lawyers moving into transactional work"]'::jsonb, '["You want contract law theory rather than drafting","You only need an NDA; there are free ones","You need US or EU-governed templates; this is Indian law throughout"]'::jsonb, '[{"q":"Are the templates editable?","a":"Yes. Every template is a Word document you can adapt. They are starting points, not substitutes for judgement."},{"q":"Is there a module on open source?","a":"Open-source audits are covered inside the software module. A dedicated open-source compliance course is planned for 2027."}]'::jsonb, 3, false, false, true, now())
on conflict (slug) do update set subtitle = excluded.subtitle, summary = excluded.summary, area = excluded.area, level = excluded.level, duration = excluded.duration, unit = excluded.unit, unit_note = excluded.unit_note, access = excluded.access,
  outcomes = excluded.outcomes, about = excluded.about, includes = excluded.includes, kit = excluded.kit, who_for = excluded.who_for, not_for = excluded.not_for, faq = excluded.faq, sort_order = excluded.sort_order, featured = excluded.featured, enrol_open = excluded.enrol_open, published_on_site = true, site_published_at = coalesce(public.courses.site_published_at, now());

insert into public.courses (slug, title, price_inr, active, subtitle, summary, area, level, duration, unit, unit_note, access, outcomes, about, includes, kit, who_for, not_for, faq, sort_order, featured, enrol_open, published_on_site, site_published_at)
values ('patent-drafting-and-prosecution', 'Patent Drafting and Prosecution', 14999, true, 'Draft a specification that survives examination, then prosecute it: read the FER, amend the claims, argue Section 3 and prepare for the hearing.', 'Claims first, specification second, prosecution third. Ten modules on real disclosures and real First Examination Reports, from mechanical to software to pharma.', 'Patent', 'Intermediate', 'About 26 hours', 'modules', '', 'Lifetime access',
  '["Draft a complete specification: field, background, summary, detailed description, claims and abstract, in that order of difficulty","Write an independent claim with the minimum essential features, and dependent claims that give you real fallback positions","Read a First Examination Report line by line and classify every objection by the response it needs","Respond to novelty and inventive-step objections by distinguishing D1 and D2 on the record, not by assertion","Argue Section 3(k) and Section 3(d) in the structure the Patent Office currently accepts","Amend claims under Sections 57 and 59 without broadening them, and show the basis in the specification","Prepare written submissions and an oral strategy for a hearing under Rule 28","Run the formal side: Form 3 updates, Form 18, Form 4 extensions, and the deadlines that cannot be extended"]'::jsonb, '["Most patent training in India teaches you what the Patents Act says. This course teaches you to write claims, because everything else in the file exists to support them, and to defend those claims when the examiner comes back with D1, D2 and a Section 3(k) objection.","You will draft three full claim sets and one complete specification, then prosecute two real applications from FER to hearing. The disclosures are from mechanical, software and pharmaceutical matters, so you see how the same method bends to each field.","This is the longest course we run, and the most demanding. Budget two drafting hours for every hour of video."]'::jsonb, '["28 drafting exercises with model answers","Two complete prosecution files, FER to hearing","Claim drafting checklist and specification skeleton","FER response templates by objection type","Hearing submission template","Monthly live drafting clinic, replays included","Lifetime access and updates"]'::jsonb, null, '["Associates and patent agents in their first three years of drafting","Engineers and scientists preparing for the patent agent examination who want the practical half","In-house counsel at product companies who instruct outside patent counsel","Litigators who need to read a prosecution history properly"]'::jsonb, '["You have never read a claim and are not willing to read fifty","You want a bar-exam style survey of patent law","You need PCT or foreign prosecution strategy; this is India-first"]'::jsonb, '[{"q":"Do I need a technical degree?","a":"No, but you need to be comfortable reading technical descriptions. The mechanical and software examples are chosen to be understandable with care rather than expertise."},{"q":"Does this prepare me for the patent agent exam?","a":"It prepares you for Paper II, the drafting paper, better than anything else we know of. It does not cover Paper I, which tests the Act and Rules."}]'::jsonb, 2, false, false, true, now())
on conflict (slug) do update set subtitle = excluded.subtitle, summary = excluded.summary, area = excluded.area, level = excluded.level, duration = excluded.duration, unit = excluded.unit, unit_note = excluded.unit_note, access = excluded.access,
  outcomes = excluded.outcomes, about = excluded.about, includes = excluded.includes, kit = excluded.kit, who_for = excluded.who_for, not_for = excluded.not_for, faq = excluded.faq, sort_order = excluded.sort_order, featured = excluded.featured, enrol_open = excluded.enrol_open, published_on_site = true, site_published_at = coalesce(public.courses.site_published_at, now());

insert into public.courses (slug, title, price_inr, active, subtitle, summary, area, level, duration, unit, unit_note, access, outcomes, about, includes, kit, who_for, not_for, faq, sort_order, featured, enrol_open, published_on_site, site_published_at)
values ('trademark-prosecution-in-practice', 'Trademark Prosecution in Practice', 7999, true, 'Ten recorded sessions that take one mark from the first search to the hearing notice: search reports, risk calls, examination report responses and written submissions, drafted the way the Registry expects them.', 'The complete prosecution cycle in ten two-hour sessions, all recorded. Half the course is the pre-filing search most juniors are never taught properly; the other half is the examination report, the written submission and the hearing. Ten practice exercises, email support throughout, and a community of IP professionals.', 'Trademark', 'Beginner to intermediate', '20 hours', 'sessions', '2 hours each, recorded', 'Recording access for 2 months from the date of registration',
  '["Classify a proposed mark and predict its Section 9 and Section 11 exposure before anyone files","Build search strings that find phonetic, visual and transliterated variants the plain search misses","Prepare a complete pre-filing search report with a risk opinion a client can act on","Run dilution, proprietor and WIPO Global Brand Database searches, and know when transborder reputation matters","Read a Registry examination report in minutes and choose the right route for each objection","Draft a response to a Section 9 or Section 11 objection with the evidence index to back it","Prepare written submissions and a hearing file that survive the hearing officer''s questions","Keep a prosecution docket clean: deadlines, file hygiene and the records the Registry will ask for"]'::jsonb, '["Most trademark training starts at the examination report. This course starts earlier, where the real decisions are made: the search. Six of the ten sessions are about finding what is already on the Register and on the market, reading it under Sections 9, 11 and 17, and writing an opinion that tells the client whether to file, change the mark, or walk away.","The second half is prosecution proper. You read real Registry examination reports, choose the route for each objection, draft the response, and then prepare the written submission and hearing file for the matters that are not waived. Two sessions are pure demonstration: a search report and a response drafted live, start to finish, and a final walk-through of one mark from the first search to the hearing notice.","Every session is recorded, and the recordings stay open to you for two months from the date you register: long enough to work through all ten at a session a week with time to spare, and to return to the parts you need on a live matter. Ten practice exercises, one per session, come with model answers. Questions go by email and are answered by the people who teach the course. Enrolling also places you in the VIDIKSHA community of IP professionals, where practitioners compare notes on real objections and Registry practice.","You also receive the IP Prosecution Kit at your doorstep: the Vidiksha Trademark Prosecution in Practice book, the prosecution and filing checklists, and the sample drafts the course is built around, printed, so they are on your desk when a real examination report lands."]'::jsonb, '["10 recorded sessions, 2 hours each, available for 2 months from registration","10 practice exercises with model answers","Email support from the instructors throughout the course","Membership of the VIDIKSHA community of IP professionals","IP Prosecution Kit delivered to your doorstep","Certificate on completion of all ten exercises"]'::jsonb, '{"title":"IP Prosecution Kit","intro":"A physical kit, couriered to the address you give at registration, so the references you need at your desk are on paper and not in a tab.","items":["Vidiksha Trademark Prosecution in Practice book","Prosecution checklist","Checklist for filing a trademark","Sample drafts: examination report responses, written submissions, Section 9 clearance, Section 11 clearance and common-law clearance"]}'::jsonb, '["Junior associates handling trademark searches and examination reports for the first time","In-house counsel who review outside counsel''s search reports and prosecution work","Founders who want to clear and file their own marks with open eyes","Final-year law students who want a job that involves this"]'::jsonb, '["You want a survey of trademark doctrine","You have never opened the Trade Marks Act and want to start there","You do only litigation and never touch the Registry"]'::jsonb, '[{"q":"Are the sessions live or recorded?","a":"Recorded. All ten sessions are available from the day you enrol, so you can watch at your own pace and go back to a session when a live matter needs it. Questions go by email and are answered by the instructors."},{"q":"How long do I have access to the recordings?","a":"Two months from the date of registration. That is comfortably enough for the ten sessions and the exercises; if you need longer for a good reason, write to us before the period ends."},{"q":"What is in the IP Prosecution Kit, and how does it reach me?","a":"The Vidiksha Trademark Prosecution in Practice book, the prosecution checklist, the checklist for filing a trademark, and printed sample drafts for examination report responses, written submissions, and Section 9, Section 11 and common-law clearances. It is couriered to the address you give at registration, within India."},{"q":"What is the community?","a":"A private group of VIDIKSHA members who practise IP: associates, in-house counsel, agents and founders. It is where people compare notes on real objections, hearing experiences and Registry practice, and where we post updates when practice changes."},{"q":"Which Registry practice does this follow?","a":"Indian practice under the Trade Marks Act, 1999 and the Trade Marks Rules, 2017, as applied by the Registry today. Sessions are re-recorded when practice changes."},{"q":"Are the documents real?","a":"Yes. Search reports, examination reports, responses, written submissions and hearing records from actual matters, with client and mark details altered where needed."}]'::jsonb, 1, true, true, true, now())
on conflict (slug) do update set subtitle = excluded.subtitle, summary = excluded.summary, area = excluded.area, level = excluded.level, duration = excluded.duration, unit = excluded.unit, unit_note = excluded.unit_note, access = excluded.access,
  outcomes = excluded.outcomes, about = excluded.about, includes = excluded.includes, kit = excluded.kit, who_for = excluded.who_for, not_for = excluded.not_for, faq = excluded.faq, sort_order = excluded.sort_order, featured = excluded.featured, enrol_open = excluded.enrol_open, published_on_site = true, site_published_at = coalesce(public.courses.site_published_at, now());

